import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Learning spells","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/learning-spells.md","filePath":"en/guide/magic/learning-spells.md"}'),r={name:"en/guide/magic/learning-spells.md"};function s(l,e,o,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="learning-spells" tabindex="-1">Learning spells <a class="header-anchor" href="#learning-spells" aria-label="Permalink to &quot;Learning spells&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Core Patterns are learned spell identities; Magery measures execution.</li><li>Teachers, books and exploration can expand knowledge beyond skill thresholds.</li><li>Ordinary casting scrolls do not permanently teach; preparation and Familiarity remain separate.</li></ul><p><a href="/Syrolands-Public/en/game-design/magic/spell-knowledge.html">Full design specification</a></p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Proposed role / boundary</th></tr></thead><tbody><tr><td>Capability</td><td>Knowing a spell and having enough Magery to use it reliably are different achievements. Reaching a skill threshold would not automatically unlock a spell or guarantee success.</td></tr><tr><td>Core Patterns and discovery</td><td>A Core Pattern is the learned identity of a spell, such as an illustrative Fireball or Remove Curse. Teachers, academies, cultures, ruins, manuscripts, magical sites, creatures, rituals and experimentation could expand your knowledge. Appropriate player teaching remains a possibility with rules still to design.</td></tr><tr><td>Practice and preparation</td><td>Familiarity grows around individual patterns rather than spending more skillcap. Wider schools and specialization remain distinct. <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Active Memory</a> determines prepared access; an ordinary casting scroll does not permanently teach its spell.</td></tr><tr><td>Open questions</td><td>The proposal retains useful early magic and long-term discovery. Exact learning gates, gain and restrictions remain undecided.</td></tr></tbody></table>',7)])])}const u=a(r,[["render",s]]);export{h as __pageData,u as default};
